select coalesce(jsonb_agg(t.failed),'[]'::jsonb)as failures from (select 'ece:official:equipment:es:23f23e21a5e68c1fae048f09' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:23f23e21a5e68c1fae048f09' and payload#>'{features}'=$verify_4a48d0c039253fa2$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes usar una acción adicional para lanzar esta espada mágica al aire y pronunciar la palabra de activación. Cuando lo hagas, el arma comenzará a levitar, volará hasta 9 m y atacará a una criatura de tu elección que esté a 1,5 m o menos de ella. La espada utiliza tu tirada de ataque y tu modificador por característica para las tiradas de daño.\n\nMientras la espada esté levitando, podrás emplear una acción adicional para que vuele hasta 9 m hacia otro lugar situado a 9 m o menos de ti. Como parte de la misma acción adicional, podrás hacer que la espada ataque a una criatura situada a 1,5 m o menos de ella.\n\nDespués de que la espada flotante ataque por cuarta vez, volará hasta 9 m y tratará de regresar a tu mano. Si no tienes ninguna mano libre, caerá a tus pies. Si la espada tiene vía libre hasta ti, se te acercará todo lo que pueda y después caerá al suelo. También dejará de levitar si la agarras o si te alejas más de 9 m de ella.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4a48d0c039253fa2$::jsonb and revision=3) union all select 'ece:official:equipment:es:240e4ce5f914087a513da6a2' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:240e4ce5f914087a513da6a2' and payload#>'{description}'=$verify_f3ae9b4fecfd8020$"Objeto · Precio base · Peso\nCantimplora · 2 pp · 5 lb (llena)\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_f3ae9b4fecfd8020$::jsonb and payload#>'{rules,definition,description}'=$verify_0ad7a883d022e3a3$[{"id":"official-table","rows":[["Cantimplora","2 pp","5 lb (llena)"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_0ad7a883d022e3a3$::jsonb and revision=3) union all select 'ece:official:equipment:es:24a89eb8efb8617f0eecf7e4' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:24a89eb8efb8617f0eecf7e4' and payload#>'{features}'=$verify_6f7347b1b4da5195$[{"id":"withering-hit","kind":"other","name":"Marchitamiento","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"2d10"}],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Este bastón tiene 3 cargas y recupera 1d3 cargas empleadas cada día, al amanecer.\n\nEl bastón se puede usar a modo de bastón mágico. Si impactas con él, causa daño como un bastón normal y puedes gastar 1 carga para infligir 2d10 de daño necrótico adicional al objetivo. Además, el objetivo deberá superar una tirada de salvación de Constitución con CD 15 o tendrá desventaja durante 1 hora en cualquier prueba de característica o tirada de salvación que utilice la Fuerza o la Constitución.\n\nDuración: 1 hora para la desventaja; el daño es inmediato..\n\nCoste: 1 cargas.","showInActions":false}]$verify_6f7347b1b4da5195$::jsonb and revision=3) union all select 'ece:official:equipment:es:250884d74945e41176af6df1' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:250884d74945e41176af6df1' and payload#>'{features}'=$verify_b40b5f9186ea5148$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes un bonificador a las tiradas de ataque y de daño que hagas con esta unidad de munición mágica. El bonificador depende de la rareza de la munición. Una vez que impacte en un objetivo, la munición dejará de ser mágica.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_b40b5f9186ea5148$::jsonb and revision=3) union all select 'ece:official:equipment:es:2576abf7d0b4aa35a244426d' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2576abf7d0b4aa35a244426d' and payload#>'{features}'=$verify_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4ca76cc6ddf1af62$::jsonb and revision=3) union all select 'ece:official:equipment:es:25c626a208ba4a32f000c0d0' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:25c626a208ba4a32f000c0d0' and payload#>'{features}'=$verify_29a45bdffabc85d9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto del conjuro clarividencia. En este líquido amarillento flota un globo ocular, pero desaparece en cuanto se abre la poción.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_29a45bdffabc85d9$::jsonb and revision=3) union all select 'ece:official:equipment:es:25d11d7b5a7b5c94a5f9c0c8' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:25d11d7b5a7b5c94a5f9c0c8' and payload#>'{features}'=$verify_7b31b792807934b9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, tendrás resistencia a un tipo de daño. La gema incrustada en el anillo, que tu GM elige o determina al azar, indica el tipo de daño.\n\n1 · Ácido · Perla\n2 · Frío · Turmalina\n3 · Fuego · Granate\n4 · Fuerza · Zafiro\n5 · Necrótico · Azabache\n6 · Psíquico · Jade\n7 · Radiante · Topacio\n8 · Relámpago · Citrino\n9 · Trueno · Espinela\n10 · Veneno · Amatista\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_7b31b792807934b9$::jsonb and payload#>'{rules,personalDescription}'=$verify_6075c158ee2d28a5$"Tienes resistencia a un tipo de daño mientras llevas este anillo. La gema del anillo indica el tipo, que el DM elige o determina aleatoriamente.\n-1-Acido-Perla\n-2-Frio-Turmalina\n-3-Fuego-Granate\n-4-Fuerza-Zafiro\n-5-Relámpago-Citrino\n-6-Necrótico-Azabache.\n-7-Veneno-Amatista\n-8-Psíquico-Jade\n-9-Radiante-Topacio\n-10-Trueno-Espinela"$verify_6075c158ee2d28a5$::jsonb and revision=3) union all select 'ece:official:equipment:es:27449e1bed6d4f91099fb4e4' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:27449e1bed6d4f91099fb4e4' and payload#>'{features}'=$verify_098e651649ff7d4d$[{"id":"mundane-assisted-use","kind":"other","name":"Jugar con competencia","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Set de Juego. Este objeto engloba un amplio rango de piezas de juego incluyendo dados y barajas de cartas (para juegos tales como Tres dragones). Unos pocos ejemplos comunes aparecen en la tabla Herramientas pero existen otro tipo de sets de juego. Si eres competente con un set de juego puedes añadir tu bonificador de competencia a las pruebas de característica que realices para jugar a un juego con este set. Cada tipo de set de juego requiere una competencia por separado.\n\nDuración: Según su uso..","showInActions":false}]$verify_098e651649ff7d4d$::jsonb and revision=4) union all select 'ece:official:equipment:es:283d43a7fbb28f2f5d081a4d' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:283d43a7fbb28f2f5d081a4d' and payload#>'{features}'=$verify_9e343969c674a850$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 de sus cargas y elegir un objetivo a 36 m o menos de ti. El objetivo puede ser una criatura, un objeto o un punto en el espacio. Tira 1d100 y consulta la tabla que aparece a continuación para descubrir lo que ocurrirá.\n\nSi el efecto hace que lances un conjuro con la varita, la CD de salvación será 15. Si el conjuro tiene normalmente un alcance expresado en metros, su alcance pasará a ser de 36 m (si no lo era ya).\n\nSi un efecto cubre un área, deberás centrar el conjuro en el objetivo e incluirlo en su interior. Si un efecto tiene varios objetivos posibles, tu GM determinará al azar cuáles se verán afectados.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en polvo y se destruye.\n\n01–05 · Lanzas ralentizar.\n06–10 · Lanzas fuego feérico.\n11–15 · Crees que algo asombroso acaba de ocurrir, por lo que te quedas aturdido hasta el principio de tu siguiente turno.\n16–20 · Lanzas ráfaga de viento.\n21–25 · Lanzas detectar pensamientos sobre el objetivo que elijas. Si no has hecho objetivo a una criatura, en vez de eso, recibirás 1d6 de daño psíquico.\n26–30 · Lanzas nube apestosa.\n31–33 · Una lluvia intensa cae en un radio de 18 m centrado en el objetivo. La zona se vuelve ligeramente oscura. La lluvia cae hasta el principio de tu siguiente turno.\n34–36 · Un animal aparece en el espacio sin ocupar más cercano al objetivo. El animal no se encuentra bajo tu control y actúa con normalidad. Tira 1d100 para determinar qué animal aparece. Si el resultado es 01-25, aparecerá un rinoceronte; si es 26-50, aparecerá un elefante, y con 51-100, aparecerá una rata.\n37–46 · Lanzas relámpago.\n47–49 · Una nube de 600 mariposas de gran tamaño cubre un radio de 9 m centrado en el objetivo. La zona se vuelve muy oscura. Las mariposas permanecen durante 10 minutos.\n50–53 · Aumentas el tamaño del objetivo como si hubieras lanzado agrandar/reducir. Si el objetivo no puede verse afectado por ese conjuro o si no has hecho objetivo a una criatura, tú te convertirás en el objetivo.\n54–58 · Lanzas oscuridad.\n59–62 · La hierba crece en el suelo en un radio de 18 m centrado en el objetivo. Si ya había hierba allí, crecerá hasta diez veces su tamaño normal y tendrá ese tamaño durante 1 minuto.\n63–65 · Un objeto a elección de tu GM desaparece en el Plano Etéreo. El objeto no puede medir más de 3 m en ninguna dimensión, debe encontrarse a 36 m o menos del objetivo y nadie puede vestirlo o llevarlo.\n66–69 · Encoges como si hubieras lanzado agrandar/reducir sobre ti.\n70–79 · Lanzas bola de fuego.\n80–84 · Lanzas invisibilidad sobre ti.\n85–87 · Crecen hojas en el objetivo. Si eliges un punto en el espacio como objetivo, las hojas brotan de la criatura más cercana a ese punto. Salvo que se arranquen, las hojas se volverán marrones y caerán tras 24 horas.\n88–90 · Una ráfaga de 1d4 × 10 gemas, cada una con un valor de 1 po, sale disparada de la punta de la varita en una línea de 9 m de largo y 1,5 m de ancho. Cada gema hace 1 de daño contundente y el total de daño de las gemas se divide a partes iguales entre todas las criaturas situadas en la línea.\n91–95 · Una explosión de luz resplandeciente y colorida se extiende desde ti en un radio de 9 m. Todas las criaturas que puedan ver en el área y tú deberéis superar una tirada de salvación de Constitución con CD 15 o quedaréis cegados durante 1 minuto. Una criatura puede repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto.\n96–97 · La piel del objetivo se vuelve azul brillante durante 1d10 días. Si has elegido un punto en el espacio como objetivo, la criatura más cercana a ese punto será quien sufra el efecto.\n98–00 · Si tu objetivo es una criatura, deberá hacer una tirada de salvación de Constitución con CD 15. Si no has hecho objetivo a una criatura, tú te convertirás en el objetivo y deberás hacer la tirada de salvación. Si la falla por 5 o más, el objetivo quedará petrificado instantáneamente. Si la falla con otro resultado, el objetivo quedará apresado y comenzará a convertirse en piedra. Mientras el objetivo esté apresado de esta forma, deberá repetir la tirada de salvación al final de su siguiente turno; quedará petrificado si la falla o se librará del efecto si la supera. La petrificación dura hasta que el objetivo sea liberado mediante un conjuro restablecimiento mayor u otro efecto mágico similar.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_9e343969c674a850$::jsonb and payload#>'{rules,personalDescription}'=$verify_109e450eded382da$"Esta varita tiene 7 cargas. Mientras la sostienes, puedes usar una acción para gastar 1 de sus cargas y elegir un objetivo a 120 pies o menos de ti. El objetivo puede ser una criatura, un objeto o un punto en el espacio. Tira d100 y consulta la siguiente tabla para descubrir qué sucede. Si el efecto hace que lances un hechizo desde la varita, la CD de salvación del hechizo es 15. Si el hechizo normalmente tiene un alcance expresado en pies, su alcance se convierte en 120 pies si no lo es ya. Si un efecto cubre un área, debes centrar el hechizo en el objetivo e incluirlo. Si un efecto tiene múltiples objetivos posibles, el DM determina aleatoriamente cuáles son los afectados.\n\nLa varita recupera 1d6 + 1 de las cargas gastadas diariamente al amanecer. Si gastas la última carga de la varita, tira 1d20. Con un 1, la varita se deshace en polvo y queda destruida.\n\n01-05 - Lanzas lento.\n06-10 - Lanzas fuego feérico.\n11-15 - Quedas aturdido hasta el comienzo de tu siguiente turno, creyendo que algo increíble acaba de suceder.\n16-20 - Lanzas ráfaga de viento.\n21-25 - Lanzas la habilidad de detectar pensamientos al objetivo que hayas elegido. Si no elegiste a una criatura, recibes 1d6 de daño psíquico.\n26-30 - Lanzas una nube apestosa.\n31-33 - Cae una lluvia intensa en un radio de 60 pies centrado en el objetivo. El área queda ligeramente oscurecida. La lluvia cae hasta el comienzo de tu siguiente turno.\n34-36 - Aparece un animal en el espacio desocupado más cercano al objetivo. El animal no está bajo tu control y actúa como lo haría normalmente. Tira 1d100 para determinar qué animal aparece. Con un 01/25, aparece un rinoceronte; con un 26/50, aparece un elefante; y con un 51/100, aparece una rata.\n37-46 - Lanzas rayo.\n47-49 - Una nube de 600 mariposas gigantes llena un radio de 30 pies centrado en el objetivo. El área queda muy oscura. Las mariposas permanecen allí durante 10 minutos.\n50-53 - Agrandas el objetivo como si hubieras lanzado agrandar/reducir. Si el objetivo no puede verse afectado por ese hechizo, o si no elegiste a ninguna criatura como objetivo, te conviertes en el objetivo.\n54-58 - Arrojas oscuridad.\n59-62 - La hierba crece en el suelo en un radio de 60 pies centrado en el objetivo. Si ya hay hierba allí, crece hasta alcanzar diez veces su tamaño normal y permanece cubierta de maleza durante 1 minuto.\n63-65 - Un objeto elegido por el DM desaparece en el Plano Etéreo. El objeto no debe llevarse puesto ni llevarse en un radio de 120 pies del objetivo y no debe medir más de 10 pies en ninguna dimensión.\n66-69 - Te encoges como si te hubieras lanzado agrandar/reducir.\n70-79 - Lanzas bola de fuego.\n80-84 - Te lanzas invisibilidad a ti mismo.\n85-87 - Las hojas crecen del objetivo. Si eliges un punto en el espacio como objetivo, las hojas brotan de la criatura más cercana a ese punto. A menos que las arranques, las hojas se vuelven marrones y se caen después de 24 horas.\n88-90 - Un chorro de 1d4 × 10 gemas, cada una de ellas con un valor de 1 po, sale disparado desde la punta de la varita en una línea de 30 pies de largo y 5 pies de ancho. Cada gema inflige 1 punto de daño contundente, y el daño total de las gemas se divide equitativamente entre todas las criaturas de la línea. 91-95 - Una explosión de luz brillante y colorida se extiende desde ti en un radio de 30 pies. Tú y cada criatura en el área que pueda ver deben tener éxito en una tirada de salvación de Constitución CD 15 o quedarán cegados durante 1 minuto. Una criatura puede repetir la tirada de salvación al final de cada uno de sus turnos, terminando el efecto sobre sí misma si tiene éxito.\n96-97 - La piel del objetivo se vuelve azul brillante durante 1d10 días. Si elegiste un punto en el espacio, la criatura más cercana a ese punto se ve afectada. 98-00 - Si elegiste a una criatura, esta debe realizar una tirada de salvación de Constitución CD 15. Si no elegiste a una criatura, tú te conviertes en el objetivo y debes realizar la tirada de salvación. Si la tirada de salvación falla por 5 o más, el objetivo queda petrificado instantáneamente. Si falla cualquier otra tirada de salvación, el objetivo queda inmovilizado y comienza a convertirse en piedra. Mientras está inmovilizado de esta manera, el objetivo debe repetir la tirada de salvación al final de su siguiente turno, quedando petrificado si falla o terminando el efecto si tiene éxito. La petrificación dura hasta que el objetivo es liberado por el conjuro de restauración mayor o magia similar."$verify_109e450eded382da$::jsonb and revision=3) union all select 'ece:official:equipment:es:285015c1f803ed9cd52a94c8' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:285015c1f803ed9cd52a94c8' and payload#>'{features}'=$verify_1d722e423b49351b$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 de sus cargas para conjurar un delgado rayo azul que serpenteará desde la punta de la varita hacia una criatura que puedas ver a 18 m o menos de ti. El objetivo deberá superar una tirada de salvación de Constitución con CD 15 o quedará paralizado durante 1 minuto. Podrá repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_1d722e423b49351b$::jsonb and revision=3) union all select 'ece:official:equipment:es:288b0e63563a7d6ecda0925b' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:288b0e63563a7d6ecda0925b' and payload#>'{features}'=$verify_e1f13f389bea68e5$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás resistencia a un tipo de daño durante 1 hora. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$verify_e1f13f389bea68e5$::jsonb and payload#>'{rules,personalDescription}'=$verify_6cae00f70201c866$"Cuando bebes esta poción, obtienes resistencia a un tipo de daño durante 1 hora. El DM elige el tipo o lo determina aleatoriamente tirando en la siguiente tabla.\n1-Acido\n2-Frio\n3-Fuego\n4-Fuerza\n5-Relampago\n6-Necrotico\n7-Veneno\n8-Psíquico\n9-Radiante\n10-Trueno"$verify_6cae00f70201c866$::jsonb and revision=3) union all select 'ece:official:equipment:es:28901ef2614cdb26e4f09af0' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:28901ef2614cdb26e4f09af0' and payload#>'{features}'=$verify_6831ba56f10b63d2$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"La próxima vez que veas a una criatura en los 10 minutos posteriores a beber este filtro, quedarás hechizado por ella durante 1 hora. Si la criatura es de una especie y género que normalmente te atraigan, la considerarás tu amor verdadero mientras permanezcas hechizado. El líquido efervescente y de tonalidad rosa de este brebaje contiene una burbuja, fácil de pasar por alto, con forma de corazón.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_6831ba56f10b63d2$::jsonb and revision=3) union all select 'ece:official:equipment:es:29b91b0b62ab8ab131ddf0b1' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:29b91b0b62ab8ab131ddf0b1' and payload#>'{features}'=$verify_657c259537dee184$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta capa con la capucha puesta, podrás respirar bajo el agua y tendrás una velocidad nadando de 18 m. Ponerte o quitarte la capucha requiere una acción.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_657c259537dee184$::jsonb and revision=3) union all select 'ece:official:equipment:es:2b27121f4f6b49d06be83a0b' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2b27121f4f6b49d06be83a0b' and payload#>'{features}'=$verify_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4ca76cc6ddf1af62$::jsonb and revision=3) union all select 'ece:official:equipment:es:2b9317ec14536ced5520b06e' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2b9317ec14536ced5520b06e' and payload#>'{features}'=$verify_b86cf8ddf5843e97$[{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. Mientras lo empuñes, obtendrás un bonificador de +2 a las tiradas de ataque de conjuro.\n\nEl bastón tiene 50 cargas para utilizar las propiedades que se describen a continuación. Recupera 4d6 + 2 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 20, el bastón recupera 1d12 + 1 cargas.\n\nAbsorción de conjuros. Mientras empuñes el bastón, tendrás ventaja en las tiradas de salvación contra conjuros. Además, puedes usar tu reacción cuando otra criatura lance un conjuro que solo te haga objetivo a ti. Si lo haces, el bastón absorberá la magia del conjuro, cancelará su efecto y obtendrá una cantidad de cargas igual al nivel del conjuro absorbido. No obstante, si esto hace que la cantidad total de cargas del bastón supere las 50, el bastón explotará como si hubieses activado su golpe vengador (consulta más adelante).\n\nConjuros. Mientras empuñes el bastón, puedes usar una acción y gastar algunas de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros y aptitud mágica: abrir (2 cargas), bola de fuego (versión de nivel 7, 7 cargas), conjurar elemental (7 cargas), desplazamiento entre planos (7 cargas), disipar magia (3 cargas), esfera de llamas (2 cargas), invisibilidad (2 cargas), muro de fuego (4 cargas), pasamuros (5 cargas), relámpago (versión de nivel 7, 7 cargas), telaraña (2 cargas), telequinesis (5 cargas) o tormenta de hielo (4 cargas).\n\nTambién puedes usar una acción para lanzar uno de los siguientes conjuros desde el bastón sin gastar ninguna carga: agrandar/reducir, cerradura arcana, detectar magia, luz, mano de mago o protección contra el bien y el mal.\n\nGolpe vengador. Puedes usar una acción para romper el bastón de un rodillazo o contra una superficie sólida, lo que ejecuta un golpe vengador. El bastón se destruye y libera la magia que le queda a modo de explosión que se extiende para cubrir una esfera de 9 m de radio centrada en él.\n\nTienes un 50 por ciento de probabilidad de viajar en ese instante a un plano de existencia aleatorio y evitar la explosión. Si no logras evitar el efecto, sufrirás una cantidad de daño de fuerza igual a 16 veces el número de cargas del bastón. Todas las demás criaturas situadas en esa zona deberán hacer una tirada de salvación de Destreza con CD 17. Si la fallan, sufrirán daño conforme a la distancia a la que se encuentren del punto de origen, tal y como se muestra en la siguiente tabla. Si la superan, recibirán la mitad de ese daño.\n\n3 m de distancia o más · 8 veces el número de cargas\ncerca · del bastón\nDe 4 m a 6 m de · 6 veces el número de cargas\ndistancia · del bastón\nDe 7 m a 9 m de · 4 veces el número de cargas\ndistancia · del bastón\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. Mientras lo empuñes, obtendrás un bonificador de +2 a las tiradas de ataque de conjuro.\n\nEl bastón tiene 50 cargas para utilizar las propiedades que se describen a continuación. Recupera 4d6 + 2 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 20, el bastón recupera 1d12 + 1 cargas.\n\nAbsorción de conjuros. Mientras empuñes el bastón, tendrás ventaja en las tiradas de salvación contra conjuros. Además, puedes usar tu reacción cuando otra criatura lance un conjuro que solo te haga objetivo a ti. Si lo haces, el bastón absorberá la magia del conjuro, cancelará su efecto y obtendrá una cantidad de cargas igual al nivel del conjuro absorbido. No obstante, si esto hace que la cantidad total de cargas del bastón supere las 50, el bastón explotará como si hubieses activado su golpe vengador (consulta más adelante).\n\nConjuros. Mientras empuñes el bastón, puedes usar una acción y gastar algunas de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros y aptitud mágica: abrir (2 cargas), bola de fuego (versión de nivel 7, 7 cargas), conjurar elemental (7 cargas), desplazamiento entre planos (7 cargas), disipar magia (3 cargas), esfera de llamas (2 cargas), invisibilidad (2 cargas), muro de fuego (4 cargas), pasamuros (5 cargas), relámpago (versión de nivel 7, 7 cargas), telaraña (2 cargas), telequinesis (5 cargas) o tormenta de hielo (4 cargas).\n\nTambién puedes usar una acción para lanzar uno de los siguientes conjuros desde el bastón sin gastar ninguna carga: agrandar/reducir, cerradura arcana, detectar magia, luz, mano de mago o protección contra el bien y el mal.\n\nGolpe vengador. Puedes usar una acción para romper el bastón de un rodillazo o contra una superficie sólida, lo que ejecuta un golpe vengador. El bastón se destruye y libera la magia que le queda a modo de explosión que se extiende para cubrir una esfera de 9 m de radio centrada en él.\n\nTienes un 50 por ciento de probabilidad de viajar en ese instante a un plano de existencia aleatorio y evitar la explosión. Si no logras evitar el efecto, sufrirás una cantidad de daño de fuerza igual a 16 veces el número de cargas del bastón. Todas las demás criaturas situadas en esa zona deberán hacer una tirada de salvación de Destreza con CD 17. Si la fallan, sufrirán daño conforme a la distancia a la que se encuentren del punto de origen, tal y como se muestra en la siguiente tabla. Si la superan, recibirán la mitad de ese daño.\n\n3 m de distancia o más · 8 veces el número de cargas\ncerca · del bastón\nDe 4 m a 6 m de · 6 veces el número de cargas\ndistancia · del bastón\nDe 7 m a 9 m de · 4 veces el número de cargas\ndistancia · del bastón\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_b86cf8ddf5843e97$::jsonb and payload#>'{rules,personalDescription}'=$verify_8b9b4248e9d7e0fc$"Este bastón puede ser usado como un bastón mágico que otorga un bonificador +2 a las tiradas de ataque y daño realizadas con él. Mientras lo sostienes, obtienes un bonificador +2 a las tiradas de ataque con conjuros. El bastón tiene 50 cargas para las siguientes propiedades. Recupera 4d6 + 2 cargas gastadas diariamente al amanecer. Si gastas la última carga, tira 1d20. Con un 20, el bastón recupera 1d12 + 1 cargas.\n\n-Absorción de hechizos. Mientras sostienes el bastón, tienes ventaja en las tiradas de salvación contra hechizos. Además, puedes usar tu reacción cuando otra criatura lanza un hechizo que solo te afecta a ti. Si lo haces, el bastón absorbe la magia del hechizo, cancelando su efecto y obteniendo una cantidad de cargas igual al nivel del hechizo absorbido. Sin embargo, si al hacerlo, la cantidad total de cargas del bastón supera las 50, el bastón explota como si hubieras activado su ataque vengativo (ver más abajo).\n\n-Conjuros. Mientras sostienes el bastón, puedes usar una acción para gastar algunas de sus cargas y lanzar uno de los siguientes conjuros desde él, usando tu CD de salvación de conjuros y tu aptitud para lanzar conjuros: conjurar elemental (7 cargas), disipar magia (3 cargas), bola de fuego (versión de nivel 7, 7 cargas), esfera llameante (2 cargas), tormenta de hielo (4 cargas), invisibilidad (2 cargas), derribo (2 cargas), rayo (versión de nivel 7, 7 cargas), atravesar muro (5 cargas), desplazamiento de plano (7 cargas), telequinesis (5 cargas), muro de fuego (4 cargas) o telaraña (2 cargas). También puedes usar una acción para lanzar uno de los siguientes conjuros desde el bastón sin usar ninguna carga: bloqueo arcano, detectar magia, agrandar/reducir, luz, mano de mago o protección contra el mal y el bien.\n\n-Golpe vengativo. Puedes usar una acción para romper el bastón sobre tu rodilla o contra una superficie sólida, realizando un golpe vengativo. El bastón se destruye y libera su magia restante en una explosión que se expande para llenar una esfera de 30 pies de radio centrada en él. Tienes un 50 por ciento de probabilidad de viajar instantáneamente a un plano de existencia aleatorio, evitando la explosión. Si no logras evitar el efecto, recibes daño de fuerza igual a 16 × el número de cargas en el bastón. Todas las demás criaturas en el área deben realizar una tirada de salvación de Destreza CD 17. Si falla la tirada de salvación, una criatura recibe una cantidad de daño basada en lo lejos que está del punto de origen, como se muestra en la siguiente tabla. Si tiene éxito, una criatura recibe la mitad de daño.\n\nA 10 pies de distancia o más cerca: 8 veces el número de cambios en el personal\nDe 11 a 20 pies de distancia - 6 veces el número de cambios en el personal\nDe 21 a 30 pies de distancia - 4 veces la cantidad de cargas en el personal"$verify_8b9b4248e9d7e0fc$::jsonb and revision=3) union all select 'ece:official:equipment:es:2bc2a95f6395e248236a47ab' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2bc2a95f6395e248236a47ab' and payload#>'{features}'=$verify_3d20682e3808f6a0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para soplar este cuerno. Como respuesta, varios espíritus guerreros del Valhalla aparecerán a 18 m o menos de ti. Utilizan el perfil del berserker. Regresarán al Valhalla después de 1 hora o cuando sus puntos de golpe se reduzcan a 0. Una vez que utilices el cuerno, no podrás volver a usarlo hasta que hayan pasado 7 días.\n\nSe conoce la existencia de cuatro tipos de cuerno del Valhalla, cada uno hecho de un metal distinto. El tipo de cuerno determina cuántos berserkers responden a su llamada, así como el requisito para utilizarlo. Tu GM elige el tipo de cuerno o lo determina al azar.\n\n01–40 · Plata · 2d4 + 2 · Ninguno\n41–75 · Oropel · 3d4 + 3 · Competencia con todas las armas sencillas\n76–90 · Bronce · 4d4 + 4 · Competencia con todas las armaduras medias\n91–00 · Hierro · 5d4 + 5 · Competencia con todas las armas marciales\n\nSi soplas el cuerno sin cumplir su requisito, los berserkers invocados te atacarán. Si cumples el requisito, serán amistosos contigo y tus compañeros, y seguirán tus órdenes.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_3d20682e3808f6a0$::jsonb and revision=3) union all select 'ece:official:equipment:es:2bda57073d4de65a9fc99b84' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2bda57073d4de65a9fc99b84' and payload#>'{features}'=$verify_2268b2509e814df7$[{"id":"official-use","kind":"passive","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este amuleto, permanecerás oculto ante la magia de adivinación. No podrás ser objetivo de ningún efecto mágico de ese tipo ni podrán percibirte mediante sensores mágicos de escudriñamiento.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_2268b2509e814df7$::jsonb and revision=3) union all select 'ece:official:equipment:es:2ce971dab6d5fa7c121bc193' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2ce971dab6d5fa7c121bc193' and payload#>'{features}'=$verify_aaf89e7b6a02353d$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto del conjuro acelerar durante 1 minuto (no requiere concentración). El líquido amarillo de este brebaje tiene vetas negras y forma remolinos.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_aaf89e7b6a02353d$::jsonb and revision=3) union all select 'ece:official:equipment:es:2d00d208f92c4357d88f466e' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2d00d208f92c4357d88f466e' and payload#>'{features}'=$verify_fc57461b72b10b78$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para pronunciar la palabra de activación de la alfombra y hacer que levite y vuele. Se moverá según las indicaciones verbales que le des, siempre y cuando estés a 9 m o menos de distancia de ella.\n\nExisten cuatro tamaños de alfombra voladora. TU GM elige el tamaño o lo determina al azar.\n\n01–20 90 cm × 1,5 m ·  · 100 kg · 24 m\n21–55 1,2 m × 1,8 m ·  · 200 kg · 18 m\n56–80 1,5 m × 2,1 m ·  · 300 kg · 12 m\n81–100 1,8 m × 2,7 m ·  · 400 kg · 9 m\n\nLa alfombra puede transportar hasta el doble del peso mostrado en la tabla, pero vuela a la mitad de su velocidad si transporta un peso superior a su capacidad normal.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_fc57461b72b10b78$::jsonb and payload#>'{rules,personalDescription}'=$verify_85837eb743374cd1$"Puedes utilizar una acción para pronunciar la palabra de activación de la alfombra y hacer que levite y vuele. Se moverá de acuerdo a tus instrucciones verbales, siempre que permanezcas a 30 pies de ella. Existen cuatro tamaños de alfombra voladora. El DM elige el tamaño o lo determina al azar.\n\n3 ft. x 5 ft. - 200 lb. - 80 feet\n4 ft. x 6 ft. - 400 lb. - 60 feet\n5 ft. x 7 ft. - 600 lb. - 40 feet\n6 ft. x 9 ft. - 800 lb. - 30 feet\nLa alfombra puede cargar hasta dos veces el peso mostrado en la tabla, pero volará a la mitad de velocidad si transporta un peso superior a su capacidad normal (la indicada en Ja tabla)."$verify_85837eb743374cd1$::jsonb and revision=3) union all select 'ece:official:equipment:es:2d32f4a1dfeb0a52c48095f1' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2d32f4a1dfeb0a52c48095f1' and payload#>'{description}'=$verify_3b91126f195b264e$"Objeto · Precio base · Peso\nÁcido (vial) · 25 po · 1 lb\n\nÁcido. Como acción, puedes esparcir el contenido de este vial sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el vial se rompa con el impacto. En ambos casos, haz un ataque a distancia contra una criatura u objeto y trata el ácido como un arma improvisada. Si impacta, el objetivo sufre 2d6 de daño de ácido.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_3b91126f195b264e$::jsonb and payload#>'{features}'=$verify_03a33af9cb8863f0$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Ácido. Como acción, puedes esparcir el contenido de este vial sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el vial se rompa con el impacto. En ambos casos, haz un ataque a distancia contra una criatura u objeto y trata el ácido como un arma improvisada. Si impacta, el objetivo sufre 2d6 de daño de ácido.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_03a33af9cb8863f0$::jsonb and payload#>'{rules,definition,description}'=$verify_a405f1f3fe336dd6$[{"id":"official-table","rows":[["Ácido (vial)","25 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Ácido. Como acción, puedes esparcir el contenido de este vial sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el vial se rompa con el impacto. En ambos casos, haz un ataque a distancia contra una criatura u objeto y trata el ácido como un arma improvisada. Si impacta, el objetivo sufre 2d6 de daño de ácido.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_a405f1f3fe336dd6$::jsonb and revision=3) union all select 'ece:official:equipment:es:2d37f163346ec0dd009ba51d' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2d37f163346ec0dd009ba51d' and payload#>'{features}'=$verify_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_c177eb09f8c78bc3$::jsonb and revision=3) union all select 'ece:official:equipment:es:2ff65e228901f70ca8f98828' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2ff65e228901f70ca8f98828' and payload#>'{features}'=$verify_6a176a5460d3e0d9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta capa y tengas la capucha puesta, las pruebas de Sabiduría (Percepción) que se hagan para verte tendrán desventaja y tú tendrás ventaja en las pruebas de Destreza (Sigilo) que hagas para esconderte, ya que el color de la capa cambia para camuflarte. Ponerte o quitarte la capucha requiere una acción.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_6a176a5460d3e0d9$::jsonb and revision=3) union all select 'ece:official:equipment:es:30656091b999872276793afc' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:30656091b999872276793afc' and payload#>'{features}'=$verify_ff5772d0bc461b80$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta esfera de hierro oxidada mide 7,5 cm de diámetro y pesa 0,5 kg. Puedes usar una acción para pronunciar la palabra de activación y lanzar la esfera contra una criatura Enorme o más pequeña que puedas ver a 18 m o menos de ti. En el recorrido del lanzamiento, la esfera se abre en una maraña de bandas de metal.\n\nRealiza una tirada de ataque a distancia con un bonificador de ataque igual a tu modificador por Destreza más tu bonificador por competencia. Si impactas, el objetivo quedará apresado hasta que utilices una acción adicional para volver a pronunciar la palabra de activación y liberarlo. Si haces esto o si el ataque yerra, las bandas se contraerán y volverán a convertirse en una esfera.\n\nCualquier criatura, incluida la que está apresada, puede emplear una acción para realizar una prueba de Fuerza con CD 20 y romper las bandas de hierro. Si la supera, el objeto se destruye y la criatura apresada se libera. Si la falla, cualquier otro intento de romper las bandas por parte de la criatura fallará automáticamente hasta que hayan transcurrido 24 horas.\n\nUna vez que se utilizan las bandas, no podrán volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_ff5772d0bc461b80$::jsonb and payload#>'{rules,personalDescription}'=$verify_1bb60076cee99854$"Esta pequeña esfera ele hierro oxidado miele 3 pulgadas de diámetro y pesa una libra. Puedes usar una acción para pronunciar la palabra de activación y lanzar la esfera contra una criatura que puedas ver, se encuentre a 60 pies o menos ele ti y sea Enorme o más pequeña. Durante el recorrido del lanzamiento. la esfera se abre en una maraña ele bandas de metal.\n\nRealiza una tirada de ataque con un bonificador igual a tu modificador de Destreza más tu bonificador por competencia. Si impactas, el objetivo queda apresado hasta que utilices una acción adicional para pronunciar de nuevo la palabra de activación y liberarle. S i haces esto, o si el ataque falla, las bandas se contraen de nuevo y se vuelven a convertir en una esfera.\n\nCualquier criatura, incluyendo la que está apresada, puede emplear una acción para realizar una prueba de Fuerza CD 20 y romper las bandas de hierro. Si tiene éxito, el objeto queda destruido y la criatura apresada se libera. Si falla, cualquier otro intento de romper las bandas que haga esa criatura durante las próximas 24 horas fallará automáticamente."$verify_1bb60076cee99854$::jsonb and revision=3) union all select 'ece:official:equipment:es:31e133f12be930aa336bc88c' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:31e133f12be930aa336bc88c' and payload#>'{features}'=$verify_bbdf4b4486601b3b$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este yelmo tiene 3 cargas. Mientras lo lleves puesto, podrás utilizar una acción y gastar 1 carga para lanzar el conjuro teletransporte desde él. El yelmo recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_bbdf4b4486601b3b$::jsonb and revision=3) union all select 'ece:official:equipment:es:34cbbbaf34a6ecc0fd73e8ca' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:34cbbbaf34a6ecc0fd73e8ca' and payload#>'{features}'=$verify_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_c177eb09f8c78bc3$::jsonb and revision=3) union all select 'ece:official:equipment:es:3534fedcf685dcdcbdddaa6c' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3534fedcf685dcdcbdddaa6c' and payload#>'{features}'=$verify_05f5187d34948d72$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este calzado ligero, podrás moverte hacia arriba, hacia abajo y de lado por superficies verticales, así como boca abajo por techos. Esta manera de moverse no requiere del uso de las manos, que quedan libres. Tienes una velocidad trepando igual a tu velocidad caminando. No obstante, las babuchas no te permiten desplazarte de esta forma por una superficie resbaladiza, como una zona cubierta por hielo o aceite.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_05f5187d34948d72$::jsonb and revision=3) union all select 'ece:official:equipment:es:35b4956012293b51dbd948f2' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:35b4956012293b51dbd948f2' and payload#>'{features}'=$verify_47ab4ab81b1e6ae0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta pesada bolsa de tela contiene 3d4 judías blancas. La bolsa pesa 250 g más 125 g por cada judía que contenga.\n\nSi tiras el contenido de la bolsa al suelo, explotará en un radio de 3 m alrededor de las judías. Todas las criaturas situadas en la zona, incluyéndote a ti, deberán realizar una tirada de salvación de Destreza con CD 15; sufrirán 5d4 de daño de fuego si la fallan o la mitad del daño si la superan. Los objetos inflamables de la zona arderán siempre y cuando no los lleve o vista alguien.\n\nSi sacas una judía de la bolsa, la plantas en tierra o arena y la riegas, la judía producirá un efecto 1 minuto después en el suelo donde la hayas plantado. Tu GM puede elegir el efecto de la siguiente tabla, determinarlo al azar o crear uno nuevo.\n\n01 · Brotan 5d4 hongos venenosos. Si una criatura come un hongo, tira un dado. Si el resultado es impar, la criatura deberá superar una tirada de salvación de Constitución con CD 15 o recibirá 5d6 de daño de veneno y quedará envenenada durante 1 hora. Si el resultado es par, la criatura obtendrá 5d6 puntos de golpe temporales que durarán 1 hora.\n02–10 · Un géiser emerge del suelo y expulsa a borbotones agua, cerveza, zumo de bayas, té, vinagre, vino o aceite (a elección de tu GM). El chorro tiene una altura de 9 m y dura 1d12 asaltos.\n11–20 · Un ent brota del suelo. Hay un 50 % de probabilidad de que sea caótico malvado y ataque.\n21–30 · Surge una estatua de piedra animada e inmóvil con tu apariencia que te amenaza verbalmente. Si la abandonas y otros se acercan, la estatua te describirá como el más vil de los villanos y mandará a los recién llegados a buscarte y atacarte. Si estás en el mismo plano de existencia que la estatua, sabrá donde estás. La estatua se volverá inanimada al cabo de 24 horas.\n31–40 · Surge una hoguera de llamas azules que arderá durante 24 horas (o hasta que la apaguen).\n41–50 · 1d6 + 6 chillones brotan del suelo.\n51–60 · 1d4 + 8 sapos de color rosa intenso salen del suelo. Si alguien toca uno de los sapos, este se transforma en un monstruo Grande o más pequeño a elección de tu GM. El monstruo permanece durante 1 minuto y luego desaparece en una nube de humo rosa intenso.\n61–70 · Un bulette hambriento sale de la tierra y ataca.\n71–80 · Crece un árbol frutal. Tiene 1d10 + 20 piezas de fruta, de las cuales 1d8 tienen los efectos de pociones determinadas al azar y otra de ellas funciona como un veneno ingerido a elección de tu GM. El árbol se desvanece tras 1 hora. La fruta recogida permanece y conserva la magia durante 30 días.\n81–90 · Aparece un nido con 1d4 + 3 huevos. Cualquier criatura que se coma uno de estos huevos deberá realizar una tirada de salvación de Constitución con CD 20. Si la supera, aumentará su puntuación de característica más baja en 1 de forma permanente (se elegirá al azar la puntuación si hay varias puntuaciones que empatan como la más baja). Si la falla, la criatura recibirá 10d6 de daño de fuerza debido a una explosión mágica interna.\n91–99 · Una pirámide con una base cuadrada de 18 m de lado emerge del suelo. En el interior hay un sarcófago que contiene a un señor de las momias. La pirámide se considera la guarida del señor de las momias y su sarcófago alberga un tesoro a elección de tu GM.\n00 · Brota un tallo de judías gigante que crece hasta la altura que decida tu GM, que también elige adónde conduce la parte superior. Por ejemplo, podría dar a un hermoso mirador, al castillo de un gigante de las nubes o a otro plano de existencia.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_47ab4ab81b1e6ae0$::jsonb and payload#>'{rules,personalDescription}'=$verify_32b6e00d588a05c4$"Dentro de esta pesada bolsa de tela hay 3d4 judías secas. La bolsa pesa 1/2 libra, más 1/4 de libra adicional por cada judía que contenga. Si vacías el contenido de la bolsa en el suelo, este explotará en un radio de 10 pies alrededor de las judías. Todas las criaturas que se encuentren en el área deberá n hacer una tirada de salvación de Destreza CD 15, sufriendo 5d4 de daño de fuego si la fallan, o la mitad de ese daño si la superan. Los objetos en el área que no lleve o vista alguien arderán. Si coges una judía de la bolsa, la plantas en tierra o arena y la riegas, producirá un efecto en el suelo 1 minuto después de ser plantada. El DM puede escoger un efecto de la siguiente tabla, determinarlo al azar o crear uno nuevo.\n01 - Brotan Sd4 hongos venenosos. Si una criatura come uno de estos hongos, tira un dado. Si el resultado es impar, la criatura deberá superar una tirada de salvación de Constitución CD 15 o recibirá Sd6 de daño de veneno y quedará envenenada durante 1 hora. Con un resultado par, la criatura ganará 5d6 puntos de golpe temporales que duran una hora.\n 02- 10 Un géiser surge del suelo, expulsando a borbotones agua, cerveza, zumo de bayas, té, vinagre, vino o aceite (a elección del DM). El chorro tiene una altura de 30 pies y dura ldl2 asaltos. \n11-20 - Del suelo brota un ent (su perfil está en el Monster Manual). Hay un 50 % de probabilidades de que esta criatura sea caótica malvada y ataque inmediatamente. \n21-30 - Aparece una estatua de piedra animada e inmóvil con tu apariencia. Te amenazará verbalmente. Si la abandonas y otros se acercan, la estatua te describirá como el más vil de los villanos y mandará a los recién llegados a buscarte y atacarte. Si estás en el mismo plano de existencia que la estatua, sabrá donde estás. Se volverá inanimada tras 24 horas.\n31-40 - Surge una hoguera de llamas azules, que arderá durante 24 horas (o hasta que sea extinguida).\n41-50 - Brotan del suelo l d6 + 6 chillones (ver el perfil en el Monster Manual).\n51-60 - Se arrastrarán, saliendo de entre la tierra, 1d4 + 8 sapos de color rosa brillante. Cuando se toque a uno, este se convertirá en un monstruo Grande o más pequeño a elección del DM. El monstruo permanecerá durante l minuto y después desaparecerá en una nube de humo rosa brillante.\n61-70 - Un bulette hambriento (ver el perfil en el Monster Manual) sale excavando de la tierra y ataca. \n71-80 - Un árbol frutal crece rápidamente en el sitio. Tiene 1d10 + 20 piezas de fruta, de las cuales 1d8 se comportan como pociones determinadas aleatoriamente y otra de ellas como un veneno ingerido a elección del DM. El árbol se desvanece en una hora. La fruta que haya sido recogida permanece y la magia se mantiene durante 30 días.\n81-90 - Aparece un nido con ld4 + 3 huevos. Cualquier criatura que coma uno de estos huevos deberá realizar una tirada de salvación de Constitución CD 20. Si tiene éxito, incrementará su puntuación de característica más baja en 1, eligiendo al azar si hay varias puntuaciones empatadas por ser la más baja. Si fa lla, la criatura recibirá 10d6 de daño de fuerza de una explosión mágica interna.\n91-99 - Una pirámide con una base de 60 pies cuadrados surge del suelo. Dentro hay un sarcófago con un señor de las momias en su interior (ver el perfil en el Monster Manual). La pirámide se considera la guarida del señor de las momias y su sarcófago contiene un tesoro a elección del DM.\n00 - Brota un tallo de judía gigante, que crece hasta la altura que el DM considere oportuno. La parte más alta da acceso a un sitio también a su elección, ya sea el castillo de un gigante de las nubes, una hermosa vista u otro plano de existencia."$verify_32b6e00d588a05c4$::jsonb and revision=3) union all select 'ece:official:equipment:es:372fde0046c3e7c354b9b95a' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:372fde0046c3e7c354b9b95a' and payload#>'{features}'=$verify_5e2c0c85cd829724$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta cuerda mide 9 m de largo y pesa 1,5 kg. Si sujetas uno de los extremos de la cuerda y utilizas una acción para pronunciar su palabra de activación, el otro extremo saldrá disparado hacia delante para enredar a una criatura que puedas ver a 6 m o menos de ti. El objetivo deberá superar una tirada de salvación de Destreza con CD 15 o quedará apresado.\n\nPuedes liberar a la criatura si usas una acción adicional para pronunciar una segunda palabra de activación. Un objetivo apresado por la cuerda puede utilizar una acción para realizar una prueba de Fuerza o Destreza (a elección del objetivo) con CD 15. Si la supera, la criatura dejará de estar apresada.\n\nLa cuerda tiene una CA de 20 y 20 puntos de golpe. Recupera 1 punto de golpe cada 5 minutos mientras tenga al menos 1 punto de golpe. Si los puntos de golpe de la cuerda se reducen a 0, se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_5e2c0c85cd829724$::jsonb and payload#>'{rules,personalDescription}'=$verify_4bebd670c254d07f$"Esta cuerda tiene 30 pies de largo y pesa 3 libras. S i sostienes un extremo de la cuerda y utilizas una acción para pronunciar su palabra de activación, el otro extremo saldrá volando para enredar a una criatura que puedas ver y que se encuentre a 20 pies o menos de ti. Esta criatura deberá superar una tirada de salvación de Destreza CD 15 o quedará apresada.\n\nPuedes liberar a la criatura empleando una acción adicional para pronunciar la segunda palabra de activación. Una criatura apresada por la cuerda puede usar su acción para realizar una prueba de Fuerza o Destreza (a su elección) con CD 15. Si tiene éxito, dejará de estar apresada.\n\nLa cuerda posee CA 20 y 20 puntos de golpe. Recupera 1 punto de golpe cada 5 minutos, mientras tenga al menos 1 punto de golpe. Si los puntos de golpe de la cuerda descienden a O, queda destruida."$verify_4bebd670c254d07f$::jsonb and revision=3) union all select 'ece:official:equipment:es:38070df72830c84b3b5c4bea' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:38070df72830c84b3b5c4bea' and payload#>'{features}'=$verify_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_c177eb09f8c78bc3$::jsonb and revision=3) union all select 'ece:official:equipment:es:3873f56f6673d7d6a8e03ffb' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3873f56f6673d7d6a8e03ffb' and payload#>'{features}'=$verify_28be7e6ab30b84f7$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto del conjuro detectar pensamientos (CD de salvación 13). En el líquido denso y morado de la poción flota una nube rosa ovoide.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$verify_28be7e6ab30b84f7$::jsonb and revision=3) union all select 'ece:official:equipment:es:39453ee81afcebaacb6be012' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:39453ee81afcebaacb6be012' and payload#>'{features}'=$verify_f210f5b75e2cfc57$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta delicada tela negra, suave como la seda, está doblada para tener las dimensiones de un pañuelo. Al desdoblarla, se convierte en una sábana circular de 1,8 m de diámetro.\n\nPuedes utilizar una acción para extender un agujero portátil y colocarlo sobre una superficie sólida o apoyado en ella, donde creará un agujero extradimensional de 3 m de profundidad. El espacio cilíndrico en el interior del agujero se encuentra en otro plano, así que no sirve para crear pasadizos. Cualquier criatura que esté en el interior de un agujero portátil abierto podrá salir de él escalando.\n\nPuedes utilizar una acción para cerrar un agujero portátil sujetando los bordes de la tela y doblándola. Al doblar la tela se cierra el agujero y cualquier criatura u objeto que haya en su interior permanecerá en el espacio extradimensional. Independientemente de su contenido, el agujero no pesa casi nada.\n\nSi se dobla, las criaturas que haya dentro del espacio extradimensional del agujero podrán utilizar una acción para realizar una prueba de Fuerza con CD 10. Si la superan, se abrirán paso hacia la salida y aparecerán a 1,5 m o menos del agujero portátil o de la criatura que lo lleve consigo. Si se mete dentro del agujero portátil a una criatura que necesite respirar, podrá sobrevivir durante 10 minutos; después, empezará a ahogarse.\n\nMeter un agujero portátil en el espacio extradimensional creado por una bolsa de contención, un morral práctico o un objeto similar destruye instantáneamente ambos objetos y abre un portal al Plano Astral. El portal se crea en el sitio en el que un objeto se introdujo dentro del otro. El portal absorbe a todas las criaturas que estén a 3 m o menos de él y las conduce a un lugar aleatorio del Plano Astral. Después, el portal se cierra. El portal solo funciona en un sentido y no puede volverse a abrir.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_f210f5b75e2cfc57$::jsonb and payload#>'{rules,personalDescription}'=$verify_0f00e0363fa566bd$"Esta delicada tela negra, suave como la seda, está doblada hasta ocupar el espacio de un pañuelo. Se despliega en una sábana circular de 6 pies de diámetro.\nPuedes usar una acción para extender un agujero portátil y colocarlo en una superficie sólida, donde creará un hueco extradimensional de 10 pies de profundidad. El espacio cilíndrico en el que existe el agujero está en otro plano, por lo que no puede emplearse para crear pasadizos. Una criatura dentro de un agujero portátil puede salir del agujero escalando.\nPuedes utilizar una acción para cerrar un agujero portátil cogiendo los bordes de la tela y doblándola. Plegarla cierra el agujero, de modo que las criaturas u objetos que estuvieran dentro permanecerán ahí. Independientemente de su conte nido, el agujero no pesa nada.\nSi este se pliega, una criatura situada dentro del espacio extradimensional podrá usar una acción para hacer una prueba de Fuerza CD 10. Si tiene éxito, consigue salir a la fuerza y aparece en un espacio a 5 pies del agujero o de la criatura que lo lleve consigo. Si una criatura que necesite respirar es colocada dentro, podrá sobrevivir durante 10 minutos, tras lo cual empieza a ahogarse.\nPoner un agujero portátil dentro del espacio extradimensional creado por un morral práctico de Heward, bolsa de contención u otro objeto similar destruye instantáneamente ambos objetos y abre un portal al Plano Astral. Se creará en el sitio donde un objeto se metió dentro del otro. Cualquier criatura que se encuentre a 10 pies del portal será absorbida a través de este a una localización aleatoria en el Plano Astral. Después, el portal se cierra. Solo funciona en un sentido y no puede ser reabierto."$verify_0f00e0363fa566bd$::jsonb and revision=3) union all select 'ece:official:equipment:es:397f56a255aa64b959bb17ad' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:397f56a255aa64b959bb17ad' and payload#>'{features}'=$verify_bdb52a76377c1eea$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando ataques a un objeto con esta espada mágica e impactes, toma el resultado máximo de los dados de daño del arma contra el objetivo.\n\nCuando ataques a una criatura con esta arma y saques un 20 en la tirada de ataque, el objetivo sufrirá 4d6 de daño cortante adicional. A continuación, tira otro d20. Si sacas un 20, seccionarás uno de los miembros del objetivo. Tu GM determinará el efecto de esta amputación. Si la criatura no tiene ningún miembro que se pueda amputar, en vez de ello, seccionarás otra parte de su cuerpo.\n\nAdemás, puedes pronunciar la palabra de activación de la espada para hacer que la hoja emita luz brillante en un radio de 3 m y luz tenue 3 m más allá. Si vuelves a pronunciar la palabra de activación o envainas la espada, apagarás la luz.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_bdb52a76377c1eea$::jsonb and revision=3) union all select 'ece:official:equipment:es:399d2fabfaca062f022b9259' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:399d2fabfaca062f022b9259' and payload#>'{features}'=$verify_b0fdb5e9b42a7c29$[{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta varita, obtendrás un bonificador a las tiradas de ataque de conjuro determinado por la rareza de la varita. Además, ignorarás la cobertura media cuando realices un ataque de conjuro.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta varita, obtendrás un bonificador a las tiradas de ataque de conjuro determinado por la rareza de la varita. Además, ignorarás la cobertura media cuando realices un ataque de conjuro.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_b0fdb5e9b42a7c29$::jsonb and revision=3) union all select 'ece:official:equipment:es:39e88b4040a225d6baa7b634' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:39e88b4040a225d6baa7b634' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_30771ecbb5fe20fa$[{"id":"official-base-table","rows":[["Maza","5 po","4 lb","1d6 contundente","+0","—"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_30771ecbb5fe20fa$::jsonb and revision=3) union all select 'ece:official:equipment:es:3a1cacc0e24f2e0b2016270d' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3a1cacc0e24f2e0b2016270d' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_961876d4f1b87a7e$[{"id":"official-base-table","rows":[["Pico de guerra","5 po","2 lb","1d8 perforante","+0","—"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_961876d4f1b87a7e$::jsonb and revision=3) union all select 'ece:official:equipment:es:3a81c2f6a557d09b39518381' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3a81c2f6a557d09b39518381' and payload#>'{features}'=$verify_3041fc769c486f0c$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta bolsa guarda un parecido superficial con una bolsa de contención, pero en realidad es el orificio de alimentación de una criatura extradimensional gigante. Poner la bolsa del revés cierra el orificio.\n\nLa criatura extradimensional vinculada a la bolsa puede sentir cualquier cosa que se meta en su interior y devora cualquier materia animal o vegetal que se introduzca por completo. Esta materia se pierde para siempre. Cuando se introduce parte de una criatura viva en la bolsa, como cuando alguien mete la mano, hay un 50 % de probabilidad de que toda la criatura se vea arrastrada al interior. Una criatura que esté dentro de la bolsa puede utilizar su acción para tratar de escapar superando una prueba de Fuerza con CD 15. Otra criatura puede utilizar su acción para meter la mano en la bolsa con el fin de sacar a una criatura, lo que logrará si supera una prueba de Fuerza con CD 20 (siempre y cuando no vaya a parar ella también al interior de la bolsa primero). Cualquier criatura que comience su turno en el interior de la bolsa será devorada y su cuerpo será destruido.\n\nSe pueden guardar objetos inanimados en la bolsa, que puede albergar 0,03 m3 de dicho material. No obstante, una vez al día, la bolsa se traga cualquier objeto que contenga y lo escupe en otro plano de existencia. Tu GM determina el momento y el plano.\n\nSi se perfora o se rasga la bolsa, se destruye y cualquier cosa que contenga se transporta a un lugar aleatorio del Plano Astral.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_3041fc769c486f0c$::jsonb and revision=3) union all select 'ece:official:equipment:es:3b1581c937cbc58988d337c0' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3b1581c937cbc58988d337c0' and payload#>'{features}'=$verify_f90f6a78613d875c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes a un infernal o muerto viviente con esta arma mágica, esa criatura recibirá 2d6 de daño radiante adicional. Si al objetivo le quedan 25 puntos de golpe o menos tras sufrir este daño, deberá superar una tirada de salvación de Sabiduría con CD 15 o será destruido. Si la supera, la criatura quedará asustada de ti hasta el final de tu siguiente turno.\n\nMientras empuñes esta arma, emitirá luz brillante en un radio de 6 m y luz tenue 6 m más allá.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_f90f6a78613d875c$::jsonb and payload#>'{rules,personalDescription}'=$verify_d26e14df57c76560$"Cuando golpeas a un Demonio o a un No Muerto con esta arma mágica, esa criatura recibe 2d6 puntos de daño Radiante adicionales. Si el objetivo tiene 25 Puntos de Golpe o menos después de recibir este daño, debe superar una tirada de salvación de Sabiduría CD 15 o será destruido. Si la tirada de salvación tiene éxito, la criatura tiene el estado de Asustado hasta el final de tu siguiente turno.\n\nLuz. Mientras sostienes esta arma, emite Luz brillante en un radio de 20 pies y Luz tenue en otros 20 pies. La competencia con una maza te permite sumar tu bonificación por competencia a la tirada de ataque de cualquier ataque que realices con ella."$verify_d26e14df57c76560$::jsonb and revision=3) union all select 'ece:official:equipment:es:3b8581124ebb69e0130f882e' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3b8581124ebb69e0130f882e' and payload#>'{features}'=$verify_49e3e80c25fd1c94$[{"id":"lance-special","kind":"other","name":"Uso de la lanza de caballería","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Lanza de caballería. Tendrás desventaja si usas una lanza de caballería para atacar a un objetivo que esté a 1,5 m o menos de ti. Además, si no estás sobre una montura, necesitarás las dos manos para empuñarla.\n\nRequiere dos manos si no se está montado.\n\nDuración: Mientras se utiliza el arma..","showInActions":false}]$verify_49e3e80c25fd1c94$::jsonb and revision=3) union all select 'ece:official:equipment:es:3ba334460d1fc2fa2a8a2a56' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3ba334460d1fc2fa2a8a2a56' and payload#>'{features}'=$verify_a5e60adaef5e7214$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta bolsa de aspecto ordinario, hecha de tela de color gris, rojizo o marrón, parece vacía. No obstante, meter la mano en su interior revela la presencia de un objeto pequeño y peludo. La bolsa pesa 250 g.\n\nPuedes usar una acción para sacar el objeto peludo de la bolsa y lanzarlo a 6 m o menos de distancia. Cuando aterrice, se transformará en la criatura que determines al tirar 1d8 y consultar la tabla que corresponda al color de la bolsa. La criatura desaparecerá al siguiente amanecer o cuando sus puntos de golpe se reduzcan a 0.\n\nLa criatura es amistosa contigo y tus compañeros y actúa en tu turno. Puedes emplear una acción adicional para decirle cómo debe moverse y qué acción debe realizar en su turno o para darle órdenes más generales, como atacar a tus enemigos. Si no recibe tales órdenes, se comportará conforme a su naturaleza.\n\nUna vez que se han extraído tres objetos peludos de la bolsa, no puede volver a utilizarse hasta el siguiente amanecer. Bolsa de trucos gris\n\n1 · Comadreja\n2 · Rata gigante\n3 · Tejón\n4 · Jabalí\n5 · Pantera\n6 · Tejón gigante\n7 · Lobo terrible\n8 · Alce gigante\n\nBolsa de trucos rojiza\n\n1 · Rata\n2 · Búho\n3 · Mastín\n4 · Cabra\n5 · Cabra gigante\n6 · Jabalí gigante\n7 · León\n8 · Oso pardo\n\nBolsa de trucos marrón\n\n1 · Chacal\n2 · Simio\n3 · Babuino\n4 · Pico de hacha\n5 · Oso negro\n6 · Comadreja gigante\n7 · Hiena gigante\n8 · Tigre\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_a5e60adaef5e7214$::jsonb and revision=3) union all select 'ece:official:equipment:es:3c51a3c091c8f10097310716' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3c51a3c091c8f10097310716' and payload#>'{description}'=$verify_908dfa734a103f7e$"Objeto · Precio base · Peso\nPetate · 1 po · 7 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_908dfa734a103f7e$::jsonb and payload#>'{rules,definition,description}'=$verify_31b34ce008f3ab23$[{"id":"official-table","rows":[["Petate","1 po","7 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_31b34ce008f3ab23$::jsonb and revision=3) union all select 'ece:official:equipment:es:3d024672d426c959fbf7c9a1' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3d024672d426c959fbf7c9a1' and payload#>'{features}'=$verify_a48bd797ee9953ab$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este tubo contiene un líquido lechoso con un fuerte olor a alcohol. Puedes utilizar una acción para verter el contenido del tubo en una superficie que esté a tu alcance. El líquido disolverá de manera instantánea hasta 0,1 m2 de adhesivo que toque, incluido el pegamento soberano.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_a48bd797ee9953ab$::jsonb and revision=3) union all select 'ece:official:equipment:es:3d2325ab1ac5aaf2b05117b8' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3d2325ab1ac5aaf2b05117b8' and payload#>'{description}'=$verify_8c5c5e9c9d1e0814$"Objeto · Precio base · Peso\nAntitoxina (vial) · 50 po · —\n\nAntitoxina. La criatura que beba el contenido de este vial obtendrá ventaja en las tiradas de salvación contra veneno durante 1 hora. No tendrá efecto en muertos vivientes o autómatas.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_8c5c5e9c9d1e0814$::jsonb and payload#>'{features}'=$verify_0f739e268f820ed0$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Antitoxina. La criatura que beba el contenido de este vial obtendrá ventaja en las tiradas de salvación contra veneno durante 1 hora. No tendrá efecto en muertos vivientes o autómatas.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_0f739e268f820ed0$::jsonb and payload#>'{rules,definition,description}'=$verify_a38957a8694717e6$[{"id":"official-table","rows":[["Antitoxina (vial)","50 po","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Antitoxina. La criatura que beba el contenido de este vial obtendrá ventaja en las tiradas de salvación contra veneno durante 1 hora. No tendrá efecto en muertos vivientes o autómatas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_a38957a8694717e6$::jsonb and revision=3) union all select 'ece:official:equipment:es:3d3aec52c044be52dd2ff23f' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3d3aec52c044be52dd2ff23f' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_3ef3ef49987bd5fd$[{"id":"official-base-table","rows":[["Estoque","25 po","2 lb","1d8 perforante","+0","Sutil"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-finesse","text":"Sutil. Cuando ataques con un arma sutil, podrás elegir realizar las tiradas de ataque y de daño con el modificador por Fuerza o con el modificador por Destreza. Eso sí, deberás usar el mismo modificador para ambas tiradas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_3ef3ef49987bd5fd$::jsonb and revision=3) union all select 'ece:official:equipment:es:3e000ccfb949f6041bdb6785' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3e000ccfb949f6041bdb6785' and payload#>'{features}'=$verify_4e2d72052ae5caa6$[{"id":"mundane-assisted-use","kind":"other","name":"Contenido del paquete","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Paquete de diplomático (39 po). Incluye un cofre, 2 estuches para mapas o pergaminos, una muda de ropas de calidad, una botella de tinta, una pluma, una lámpara, 2 frascos de aceite, 5 hojas de papel, un vial de perfume, lacre y jabón.\n\nDuración: Según su uso..","showInActions":false}]$verify_4e2d72052ae5caa6$::jsonb and revision=3) union all select 'ece:official:equipment:es:3f024215021b8d6d2f55ce10' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3f024215021b8d6d2f55ce10' and payload#>'{features}'=$verify_16212da8d792cdb7$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este polvo, que se encuentra en recipientes pequeños, se asemeja a arena muy fina. Parece ser polvo de desaparición y un conjuro identificar lo reconocerá como tal. Hay suficiente para un solo uso.\n\nCuando utilices una acción para esparcir un puñado de polvo por el aire, tú y todas las criaturas que necesiten respirar y estén a 9 m o menos de ti deberéis superar una tirada de salvación de Constitución con CD 15 o seréis incapaces de respirar mientras estornudáis de manera incontrolable. Una criatura que sufra este efecto quedará incapacitada y se asfixiará. Mientras permanezca consciente, podrá repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto. El conjuro restablecimiento menor también puede poner fin a este efecto.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_16212da8d792cdb7$::jsonb and revision=3) union all select 'ece:official:equipment:es:40a2f5363de51d6cb164abd8' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:40a2f5363de51d6cb164abd8' and payload#>'{features}'=$verify_218cded44c006dc6$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves estos brazales, serás competente con arcos cortos y largos y obtendrás un bonificador de +2 a las tiradas de daño en ataques a distancia con estas armas.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_218cded44c006dc6$::jsonb and revision=3) union all select 'ece:official:equipment:es:40b58116d37541a913e599f0' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:40b58116d37541a913e599f0' and payload#>'{features}'=$verify_916ef2de428fdc28$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras sostengas este escudo, podrás emplear una acción adicional para pronunciar su palabra de activación y darle vida. El escudo saltará de tu mano y levitará en tu espacio para protegerte como si lo embrazaras, pero dejará tus manos libres. Permanecerá animado durante 1 minuto, hasta que utilices una acción adicional para poner fin a este efecto o hasta que quedes incapacitado o mueras, momento en el que el escudo caerá al suelo o en tu mano si tienes una libre.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_916ef2de428fdc28$::jsonb and revision=3) union all select 'ece:official:equipment:es:40c309135dcff04c75eaedf9' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:40c309135dcff04c75eaedf9' and payload#>'{features}'=$verify_185896a0dd0385ab$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta túnica tiene 3 cargas y recupera 1d3 cargas empleadas cada día, al amanecer. Mientras la lleves puesta, podrás utilizar una acción y emplear 1 carga para hacer que la prenda muestre un patrón cambiante de tonos y formas deslumbrantes hasta el final de tu siguiente turno. Durante este tiempo, la túnica emite luz brillante en un radio de 9 m y luz tenue 9 m más allá. Las criaturas que puedan verte tendrán desventaja en las tiradas de ataque contra ti. Además, cualquier criatura que esté bajo la luz brillante y pueda verte cuando el poder de la túnica esté activo deberá superar una tirada de salvación de Sabiduría con CD 15 o quedará aturdida hasta que termine el efecto.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_185896a0dd0385ab$::jsonb and revision=3) union all select 'ece:official:equipment:es:412fed1c4f5ada1768df781f' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:412fed1c4f5ada1768df781f' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_5ff59ab7045a4e5a$[{"id":"official-base-table","rows":[["Látigo","2 po","3 lb","1d4 cortante","+0","Sutil, Gran alcance"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-finesse","text":"Sutil. Cuando ataques con un arma sutil, podrás elegir realizar las tiradas de ataque y de daño con el modificador por Fuerza o con el modificador por Destreza. Eso sí, deberás usar el mismo modificador para ambas tiradas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-reach","text":"Gran alcance. Cuando empleas un arma de este tipo, tu alcance aumenta en 1,5 m, tanto al atacar como a efectos de ataques de oportunidad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_5ff59ab7045a4e5a$::jsonb and revision=3) union all select 'ece:official:equipment:es:4174a78b2371715a4e15dc13' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:4174a78b2371715a4e15dc13' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_0ad8ef062dea31c7$[{"id":"official-base-table","rows":[["Tridente","5 po","4 lb","1d6 perforante","+0","Arrojadiza, Versátil","20/60","1d8"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)","Daño versátil"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-versatile","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_0ad8ef062dea31c7$::jsonb and revision=3))t;